import sys
from collections import deque

class FlowNetwork:
    def __init__(self, n):
        self.n = n
        self.source = 0
        self.sink = 2 * n + 1
        self.capacity = {}
        self.flow = {}
        self.graph = {}
        for i in range(self.source + 1, self.sink):
            self.capacity[i] = {}
            self.flow[i] = {}
            self.graph[i] = []

    def add_edge(self, u, v, capacity):
        if u not in self.capacity:
            self.capacity[u] = {}
            self.flow[u] = {}
            self.graph[u] = []
        if v not in self.capacity:
            self.capacity[v] = {}
            self.flow[v] = {}
            self.graph[v] = []

        self.capacity[u][v] = self.capacity[u].get(v, 0) + capacity
        self.capacity[v][u] = self.capacity[v].get(u, 0)

        self.flow[u][v] = self.flow[u].get(v, 0)
        self.flow[v][u] = self.flow[v].get(u, 0)

        self.graph[u].append(v)
        self.graph[v].append(u)

    def bfs(self, path):
        visited = {self.source}
        parent = {self.source: None}
        queue = deque([self.source])

        while queue:
            u = queue.popleft()
            if u == self.sink:
                break

            if u in self.capacity:
                for v in self.graph[u]:
                    if v not in visited and self.capacity[u].get(v, 0) - self.flow[u].get(v, 0) > 0:
                        visited.add(v)
                        parent[v] = u
                        queue.append(v)

        if self.sink not in parent:
            return 0, {}

        path_flow = float('inf')
        v = self.sink
        while parent[v] is not None:
            path_flow = min(path_flow, self.capacity[parent[v]][v] - self.flow[parent[v]][v])
            v = parent[v]

        v = self.sink
        path = {self.source: self.sink}
        while parent[v] is not None:
            u = parent[v]
            self.flow[u][v] = self.flow[u].get(v, 0) + path_flow
            self.flow[v][u] = self.flow[v].get(u, 0) - path_flow
            v = u

        return path_flow, path

