        return "NO"

    # Build max flow network
    source = 0
    sink = 2 * n + 1

    capacity = {i: {} for i in range(source + 1, sink)}
    flow = {i: {} for i in range(source + 1, sink)}
    graph = {i: [] for i in range(source + 1, sink)}

    for i in range(1, n + 1):
        # Source -> city i with capacity a[i-1]
        capacity[0][i] = 100000 + a[i - 1]
        capacity[i][0] = 0
        flow[0][i] = 0
        flow[i][0] = 0
        graph[0].append(i)
        graph[i].append(0)

        # City i -> sink with capacity b[i-1]
        capacity[i][sink] = 100000 + b[i - 1]
        capacity[sink][i] = 0
        flow[i][sink] = 0
        flow[sink][i] = 0
        graph[i].append(sink)
        graph[sink].append(i)

        # City i -> neighbors with infinite capacity
        for neighbor in adj[i]:
            capacity[i][neighbor] = 1000000
            capacity[neighbor][i] = 0
            flow[i][neighbor] = 0
            flow[neighbor][i] = 0
            graph[i].append(neighbor)
            graph[neighbor].append(i)

    # Dinkelbach's algorithm for max flow
    total_push = 0
    while True:
        parent = {}
        predecessor = {}
        queue = [source]

        while queue:
            u = queue.pop(0)
            if u == sink:

                break

            if u in predecessor:
                continue

            predecessor[u] = None
            for v in graph[u]:
                if v not in predecessor and capacity[u].get(v, 0) - flow[u].get(v, 0) > 0:
                    predecessor[v] = u
                    queue.append(v)

            if sink in predecessor:
                break

        if sink not in predecessor:
            break

        push = float('inf')
        cur = sink
        while cur != source:
            pred = predecessor[cur]
            push = min(push, capacity[pred][cur] - flow[pred][cur])
            cur = pred

        cur = sink
        while cur != source:
            pred = predecessor[cur]
            flow[pred][cur] += push
            flow[cur][pred] -= push
            cur = pred

        total_push += push

    # Check saturation
    can_satisfy = True
    for i in range(1, n + 1):
        if flow[i][sink] < b[i - 1]:
            can_satisfy = False
            break

    if not can_satisfy:
        return "NO"

    # Check source saturation
    for i in range(1, n + 1):
        if flow[0][i] > a[i - 1]:
            left[i] = flow[0][i] - a[i - 1]
            can_satisfy = False

    if not can_satisfy:
        return "NO"

    # Build answer matrix
    result = []
    for i in range(1, n + 1):
        line = []
        for j in range(1, n + 1):
            if i == j:
                # Staying in city
                total_into_i = 0
                for k in range(1, n + 1):
                    if i == k or k in adj[i]:
                        total_into_i = max(total_into_i, flow[k][i])

                final_count = flow[i][sink]
                stay = final_count - total_into_i

                move_out = flow[0][i]
                if move_out > stay:
                    move_out = sum([flow[i][j] for j in adj[i]])

                line.append(f"{move_out - stay}")
            else:
                if flow[i][j] > 0:
                    line.append(f"{flow[i][j]}")
                else:
