    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        def check_valid(a_arr):
            """Check if array can be cleared without superability"""
            n_arr = len(a_arr)

            # b[i] = operations between pile i and pile i+1
            b = [a_arr[0]]

            for j in range(1, n_arr - 1):
                b_val = a_arr[j] - b[-1]
                if b_val < 0:
                    return False
                b.append(b_val)

            # Final pile must be cleared
            if b[-1] != a_arr[n_arr - 1]:
                return False

            return True

        def try_solving(arr):
            """Try to solve without swap, then with each possible swap"""
            n_arr = len(arr)

            # First try without any swap
            if check_valid(arr):
                return True

            # Try each possible adjacent swap
            for i in range(n_arr - 1):
                arr_copy = arr.copy()
                arr_copy[i], arr_copy[i+1] = arr_copy[i+1], arr_copy[i]
                if check_valid(arr_copy):
                    return True

            return False

        if try_solving(a):
            result.append("YES")
        else:
            result.append("NO")

    return '\n'.join(result)

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if idx >= len(lines) or len(lines) < 1:
        return ''

    t = int(lines[idx].strip())
    idx += 1

    results = []

    for _ in range(t):
        idx += 1  # skip empty line

        if idx >= len(lines):
            break

        n = int(lines[idx].strip())
        idx += 1

        # Parse nodes
        is_leaf = [False] * n
        left_child = [0] * n
        right_child = [0] * n
        leaf_value = [0] * n

        for i in range(n):
            parts = lines[idx].strip().split()
            idx += 1
            if parts[0] == '-1':
                is_leaf[i] = False
                left_child[i] = int(parts[1])
                right_child[i] = int(parts[2])
            else:
                is_leaf[i] = True
                leaf_value[i] = int(parts[0])

        # Compute number of leaves in each subtree
        leaves_memo = {}
        def get_leaves(u):
            if u in leaves_memo:
                return leaves_memo[u]

            if is_leaf[u]:
                leaves_memo[u] = 1
            else:
                leaves_memo[u] = get_leaves(left_child[u]) + get_leaves(right_child[u])

            return leaves_memo[u]

        # Compute the game-theoretic result
        result_memo = {}
        def get_result(u):
            if u in result_memo:
                return result_memo[u]

            if is_leaf[u]:
                result_memo[u] = leaf_value[u]
            else:
                left_res = get_result(left_child[u])
                right_res = get_result(right_child[u])
                left_leaves = get_leaves(left_child[u])
                right_leaves = get_leaves(right_child[u])

                # Number of operations needed in this subtree before the merge at u
                total_ops = left_leaves + right_leaves - 1

                if total_ops % 2 == 1:
                    # Pieguy's turn - maximize
                    result_memo[u] = max(left_res, right_res)
                else:
                    # Piegirl's turn - minimize
                    result_memo[u] = min(left_res, right_res)

            return result_memo[u]

        final_result = get_result(0)
        results.append(str(final_result))

    return '\n'.join(results)

def solution(input_string):
    if not input_string.strip():
        return ''

    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    offers = []
    max_duration = 0
    for i in range(1, m + 1):
        if i < len(lines):
            l, r = map(int, lines[i].split())
            offers.append((l, r))
            max_duration = max(max_duration, r - l + 1)

    results = []
    for x in range(1, n + 1):
        if x > max_duration:
            # For x greater than any offer duration, no offers can be accepted
            results.extend([0] * (n - x + 1))
            break

        # Check if all offers have been considered
        if x > len(offers) * 2:  # Optimization heuristic
            break

        # Simulate for this x
        occupied = [False] * (n + 1)
        total_occupied = 0

        for l, r in offers:
            duration = r - l + 1
            if duration < x:
                continue

            # Check if [l, r] is completely free
            free = True
            for day in range(l, r + 1):
                if occupied[day]:
                    free = False
                    break

            if free:
                for day in range(l, r + 1):
                    occupied[day] = True
                total_occupied += duration

        results.append(str(total_occupied))

    return '\n'.join(results)

def solution(input_string):
    import sys
    sys.setrecursionlimit(500000)

    lines = input_string.strip().split('\n')
    if not lines:
        return "-1"

    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Try to find k cycles with representatives
    visited = [False] * (n + 1)
    cycles = []

    def dfs_find_cycle(start):
        """DFS to find a cycle starting from start node."""
        path = [start]
        parent = {start: -1}
        seen = {start}
        stack = [start]

        while stack:
            u = stack[-1]
            for v in adj[u]:
                if v == parent.get(u, -1):
                    continue

                if v in seen:
                    # Found back edge, cycle detected
                    idx = path.index(v)
                    cycle = path[idx:]
                    if len(cycle) >= 3:
                        # Find a representative (unvisited vertex in cycle)
                        found_rep = False
                        for node in set(cycle):
                            if not visited[node]:
                                visited[node] = True
                                found_rep = True
                                break

                        if found_rep:
                            cycles.append(cycle)
                            return True
                else:
                    seen.add(v)
                    parent[v] = u
                    stack.append(v)
                    path.append(v)

            # Pop backtracked node if no children left
            if path:
                path.pop()
            stack.pop()

        return False

    # Find k cycles
    for i in range(1, n + 1):
        if not visited[i]:
            dfs_find_cycle(i)
            if len(cycles) >= k:
                break

    # If enough cycles found, output them
    if len(cycles) >= k:
        result = ["CYCLES"]
        for cycle in cycles[:k]:
            result.append(str(len(cycle)))
            result.append(" ".join(map(str, cycle)))
        return "\n".join(result)

    # Otherwise, search for a long path using DFS with backtracking
    visited_path = [False] * (n + 1)
    current_path = []
    min_len = n // k

    def dfs_path(u, depth):
        if depth >= min_len:
            return True

        visited_path[u] = True
        current_path.append(u)

        for v in adj[u]:
            if not visited_path[v]:
                if dfs_path(v, depth + 1):
                    return True

        # Backtrack
        current_path.pop()
        visited_path[u] = False

        return False

    for start in range(1, n + 1):
        if not visited_path[start]:
            if dfs_path(start, 1):
                result = ["PATH"]
                result.append(str(len(current_path)))
                result.append(" ".join(map(str, current_path)))
                return "\n".join(result)

    return "-1"

