def solution(input_string):
    # Check for empty input
    input_string = input_string.strip()
    if not input_string:
        return "0 0 0"

    lines = input_string.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n+1):
        coords = list(map(int, lines[i].split()))
        points.append(tuple(coords))

    if n == 0:
        return "0 0 0"

    if n == 1:
        x, y, z = points[0]
        return f"{x:.6f} {y:.6f} {z:.6f}"

    def dist_sq(p1, p2):
        return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

    def dist_sq_to_center(p, center):
        return (p[0]-center[0])**2 + (p[1]-center[1])**2 + (p[2]-center[2])**2

    def sphere_from_2(p1, p2):
        cx = (p1[0] + p2[0]) / 2.0
        cy = (p1[1] + p2[1]) / 2.0
        cz = (p1[2] + p2[2]) / 2.0
        r_sq = dist_sq(p1, p2) / 4.0
        return (cx, cy, cz), r_sq

    def compute_2_points_center(d1, d2, d3, c0):
        x = c0
        y = -c1
        z = -c2

        det = a * d + b * e + c * f
        if abs(det) < 1e-12:
            det2 = det * det - a * e - b * d - c * f
            if det2 <= 0:
                return None, None, None

            numerator = sqrt(abs(det2) * b * a) if det2 > 0 else 0
            x += numerator
            y += numerator
            z += numerator

        return x, y, z

    def get_sphere_3(points):
        p1, p2, p3 = points

        center, r2 = sphere_from_2(p1, p2)
        if dist_sq_to_center(p3, center) <= r2 + 1e-10:
            return center, r2
        return None, None

    def solve_3d_4pts(p1, p2, p3, p4):
        d12 = p2[0] - p1[0]
        d13 = p3[0] - p1[0]
        d14 = p4[0] - p1[0]

        a = 2 * d12
        b = 2 * (p2[1] - p1[1])
        c = 2 * (p2[2] - p1[2])
        rhs = -d12 * (p1[0] + p2[0]) - b * (p1[1] + p2[1]) - c * (p1[2] + p2[2]) / 2

        d = 2 * d13
        e = 2 * (p3[1] - p1[1])
        f = 2 * (p3[2] - p1[2])
        rhs2 = -d12 * (p1[0] + p2[0]) - d13 * (p1[0] + p3[0]) - e * (p1[1] + p2[1]) - f * (p1[1] + p3[1]) / 2

        d = 2 * d14
        e = 2 * (p4[1] - p1[1])
        f = 2 * (p4[2] - p1[2])
        rhs3 = -d * (p1[0] + p4[0]) - e * (p1[1] + p4[1]) - f * (p1[2] + p4[2]) / 2

        det = (a*d)*e - (a*e)*d
        if abs(det) < 1e-12:
            try:
                from sympy import solve, Symbol, Matrix

                x = Symbol('x')
                y = Symbol('y')
                z = Symbol('z')

                m = Matrix([[a, b, c], [d, e, f], [2, 2, 2]])
                b_vec = Matrix([rhs, rhs2, rhs3])
                solution = m.gauss_jordan_solve(b_vec)

                if solution:
                    x_val, y_val, z_val = solution[0]
                    if abs(x_val) < 1e-12:
                        x_val = 0
                    if abs(y_val) < 1e-12:
                        y_val = 0
                    if abs(z_val) < 1e-12:
                        z_val = 0
                    return (float(x_val), float(y_val), float(z_val))
            except:
                pass

        try:
            m = Matrix([[a, b, c], [d, e, f], [2, 2, 2]])
            b_vec = Matrix([rhs, rhs2, rhs3])
            x, y, z = m.solve(b_vec)
            return (float(x), float(y), float(z))
        except:
            pass

        return None

    def get_sphere_4(points):
        p1, p2, p3, p4 = points

        center = solve_3d_4pts(p1, p2, p3, p4)
        if center:
            center = center
            r2 = dist_sq_to_center(p1, center)
            return center, r2

        try:
            from sympy import Symbol, Matrix
            a = 2*(p2[0] - p1[0])
            b = 2*(p2[1] - p1[1])
            c = 2*(p2[2] - p1[2])

            d = 2*(p3[0] - p1[0])
            e = 2*(p3[1] - p1[1])
            f = 2*(p3[2] - p1[2])

            ux = Symbol('x')
            uy = Symbol('y')
            uz = Symbol('z')

            m = Matrix([[a, b, c], [d, e, f], [1, 1, 1]])
            v = Matrix([0, -d*p1[0] + d*p2[0] - d, -e*p1[1] + e*p2[1] - e*b, -f*p1[2] + f*p2[2] - f*c])
            solution = m.solve(ux)

            center = (float(solution[0]), float(solution[1]), float(solution[2]))
            r2 = dist_sq_to_center(p1, center)
            return center, r2
        except:
            ret = solve_3d_4pts(p1, p2, p3, p4)
            if ret:
                return ret
            return get_sphere_3([p1, p2]), dist_sq(p1, p3)

    def boundary_sphere(boundary):
        if not boundary:
            return (0.0, 0.0, 0.0), 0.0
        if len(boundary) == 1:
            p = boundary[0]
            return (p[0], p[1], p[2]), 0.0
        if len(boundary) == 2:
