                return ''.join(actions)
            return None

        # Check if current state is already visited to prune
        state = (x, y, frozenset(lit_copy))
        if state in visited:
            return None

        visited.add(state)

        # Try moving in each direction
        for dx, dy, mv in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                # Check if neighbor is lit
                if (nx, ny) in lit_copy:
                    if isVisible(x, y, dx, dy):
                        new_lit = lit_copy - {(nx, ny)}
                        actions.append(mv)
                        res = backtrack(nx, ny, actions, new_lit)
                        if res is not None:
                            return res
                        actions.pop()
                        if res is None:
                            return None
                else:
                    # Move even if cell is unlit (still need visibility)
                    if isVisible(x, y, dx, dy):
                        new_lit = lit_copy
                        actions.append(mv)
                        res = backtrack(nx, ny, actions, new_lit)
                        if res is not None:
                            return res
                        actions.pop()
                        if res is None:
                            return None

        # Try turning on light at current position
        if (x, y) not in lit_copy and grid[x][y] == 0:
            new_lit = lit_copy | {(x, y)}
            actions.append('1')
            res = backtrack(x, y, actions, new_lit)
            if res is not None:
                return res
            actions.pop()

        # Try turning off light at current position
        if (x, y) in lit_copy:
            new_lit = lit_copy - {(x, y)}
            actions.append('2')
            res = backtrack(x, y, actions, new_lit)
            if res is not None:
                return res
            actions.pop()

        visited.discard(state)
        return None

    res = backtrack(start_x, start_y, [], set(lights_on))

    if res is not None:
        return 'YES\n' + res
    return 'NO'

