def solution(input_str):
    lines = input_str.strip().split('\n')
    lines = [l for l in lines if l.strip()]  # Remove empty lines

    if not lines:
        return 'Impossible\n'

    n, m = map(int, lines[0].split())

    edges = []
    for i in range(min(len(lines) - 1, m)):
        u, v = map(int, lines[i + 1].split())
        # Normalize each edge so u < v consistently
        edges.append((min(u, v), max(u, v)))

    # Build conflict graph
    conflict = [[False] * m for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            a, b = edges[i]
            c, d = edges[j]
            # Two chords cross if their endpoints interleave
            if (a < c < b < d) or (c < a < d < b):
                conflict[i][j] = True
                conflict[j][i] = True

    # Build adjacency list
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(m):
            if conflict[i][j]:
                adj[i].append(j)

    # Try to 2-color the conflict graph
    color = [-1] * m
    possible = True

    for start in range(m):
        if color[start] == -1:
            stack = [(start, 0)]  # (vertex, color)
            while stack:
                u, c = stack.pop()
                if color[u] != -1 and color[u] != c:
                    possible = False
                    break
                color[u] = c
                for v in adj[u]:
                    if color[v] == -1:
                        stack.append((v, 1 - c))
            if not possible:
                break

    if not possible:
        return 'Impossible\n'

    # Build answer: 'i' for color 0 (inside), 'o' for color 1 (outside)
    result = ['i' if color[i] == 0 else 'o' for i in range(m)]
    return ''.join(result) + '\n'

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse cost matrix (assuming symmetric costs)
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j == i:
                continue
            cost[i][j] = parts[idx]
            cost[j][i] = parts[idx]  # Assume symmetric
            idx += 1

    # If n is odd, impossible to perfectly match
    if n % 2 != 0:
        return "-1"

    if n == 2:
        return "2\n1"

    # Helper: generate all perfect matchings
    def gen_matchings(first, used, matching):
        if len(matching) == n // 2:
            return [list(matching)]

        results = []
        for j in range(first + 1, n):
            if not used[j]:
                matching.append((first, j))
                used[first] = used[j] = True

                results.extend(gen_matchings(first + 1, used, matching))

                matching.pop()
                used[first] = used[j] = False

        return results

    # Helper: check if a mapping is valid (symmetric)
    def is_valid(mapping, n):
        for i in range(n):
            if mapping[i] == -1:
                return False
            j = mapping[i]
            if mapping[j] != i:
                return False
        return True

    # Helper: check if a matching is stable
    def is_stable(mapping, n):
        for i in range(n):
            j = mapping[i]
            for k in range(n):
                if k < i:  # Only check pairs where k < i to avoid duplicates
                    if k == j:
                        continue
                    l = mapping[k]
                    # Check if (i,k) is a blocking pair
                    if l != -1 and l != k:  # k not matched with itself
                        # Both i and k would prefer to switch to each other
                        if cost[i][k] < cost[i][j] and cost[k][i] < cost[k][l]:
                            return False
        return True

    # Try all perfect matchings
    all_matchings = gen_matchings(0, [False] * n, [])

    for m in all_matchings:
        mapping = [-1] * n
        for a, b in m:
            mapping[a] = b
            mapping[b] = a

        if not is_valid(mapping, n):
            continue
        if is_stable(mapping, n):
            # Found stable matching
            result = ""
            for i in range(n):
                result += str(mapping[i]) + "\n"
            return result

    return "-1"

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return '0'

    try:
        n = int(lines[0])
    except ValueError:
        return '0'

    if n <= 0:
        return '0'

    cakes = []
    for i in range(1, min(n + 1, len(lines))):
        parts = lines[i].split()
        if len(parts) >= 2:
            try:
                r, h = int(parts[0]), int(parts[1])
                volume = math.pi * r * r * h
                cakes.append(volume)
            except ValueError:
                continue

    if not cakes:
        return '0'

    # Coordinate compression - map unique volumes to ranks
    sorted_volumes = sorted(set(cakes))
    volume_to_rank = {v: i + 1 for i, v in enumerate(sorted_volumes)}

    # Fenwick tree (Binary Indexed Tree) for prefix maximum queries
    size = len(sorted_volumes) + 2
    bit = [0.0] * (size + 1)

    def update(idx, val):
        """Update position idx with value val (max operation)"""
        while idx <= size:
            bit[idx] = max(bit[idx], val)
            idx += idx & (-idx)

    def query(idx):
        """Query maximum value in range [1, idx]"""
        result = 0.0
        while idx > 0:
            result = max(result, bit[idx])
            idx -= idx & (-idx)
        return result

    # DP: dp[i] = maximum volume ending at cake i
    max_volume = 0.0
    for i, vol in enumerate(cakes):
        rank = volume_to_rank.get(vol, 1)
        # Query max dp value for cakes with strictly smaller volume
        max_prev = query(rank - 1)
        current = vol + max_prev
        max_volume = max(max_volume, current)
        update(rank, current)

    return str(max_volume)

