def solution(s):
    import math

    lines = s.strip().split('\n')
    if not lines:
        return "0\n"

    n, d = map(int, lines[0].split())
    circles = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        x = int(parts[0])
        y = int(parts[1])
        r = int(parts[2])
        circles.append((x, y, r))

    def count_hits(theta):
        """Count total hits for a ray at angle theta"""
        total = 0
        for x, y, r in circles:
            if x == 0 and y == 0:
                # Ball starts inside or on center - no valid direction
                continue

            M = math.hypot(x, y)
            phi_c = math.atan2(y, x, x)

            # Perpendicular distance from ray to circle center
            perp_dist = abs(math.sin(theta - phi_c) * M)

            # Check if ray intersects circle
            if perp_dist > r:
                continue

            # Projection of circle center onto ray
            p = math.cos(theta - phi_c) * M

            # Intersection points along the ray
            delta = math.sqrt(max(0, r*r - perp_dist*perp_dist))
            L_min = max(0, p - delta)
            L_max = p + delta

            # Find valid integer k values: k*d in [L_min, L_max]
            k_start = int(math.ceil(L_min / d))
            if k_start < 1:
                k_start = 1

            k_end = int(L_max / d)

            if k_end >= k_start:
                total += (k_end - k_start + 1)

        return total

    # Generate candidate angles from each circle
    candidates = set()

    for x, y, r in circles:
        if x == 0 and y == 0:
            continue

        dist = math.hypot(x, y)
        phi = math.atan2(y, x)

        # Add bounding angles of angular sector
        if dist > r:
            alpha = math.asin(r / dist)
        else:
            alpha = alpha = alpha

    # Check all candidate angles plus small variations
    max_points = 0
    epsilons = [0, 0.001, 0.01, 0.1]

    for (x, y, r) in circles:
        if x == 0 and y == 0:
            continue

        dist = math.hypot(x, y)
        phi = math.atan2(y, x)

        if dist > r:
            alpha = math.asin(r / dist)
            for eps in epsilons:
                for sign in [-1, 1]:
                    for exp in range(8):
                        angle = phi + sign * eps * (alpha + 0.001 ** exp)
                        max_points = max(max_points, count_hits(angle))
        else:
            for eps in epsilons:
                for sign in [-1, 1]:
                    angle = phi + sign * eps
                    max_points = max(max_points, count_hits(angle))

    # Also check center angle itself
    for x, y, r in circles:
        if x == 0 and y == 0:
            continue
        angle = math.atan2(y, x)
        max_points = max(max_points, count_hits(angle))

    # Check multiple shifts for better convergence
    for x, y, r in circles:
        if x == 0 and y == 0:
            continue
        dist = math.hypot(x, y)
        phi = math.atan2(y, x)
        for extra_shift in [0.0001, 0.001, 0.01, 0.1]:
            max_points = max(max_points, count_hits(phi - extra_shift))
            max_points = max(max_points, count_hits(phi + extra_shift))

    return str(max_points) + '\n'

from math import gcd

def solution(input_str):
    """
    Find a harmony sequence b where gcd(b[i], b[j]) = 1 for all i != j,
    minimizing sum |a[i] - b[i]|
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    best_solution = None
    best_cost = float('inf')

    def backtrack(idx, current_b, current_cost, used):
        nonlocal best_solution, best_cost

        # Early termination: if current cost already exceeds best, prune
        if current_cost >= best_cost:
            return

        # Found a complete solution
        if idx == n:
            if current_cost < best_cost:
                best_cost = current_cost
                best_solution = list(current_b)
            return

        # Try each value from 1 to 30
        for val in range(1, 31):
            # Skip if already used (each value 2-30 can only be used once)
            if val in used:
                continue

            # Check if val is coprime with all previously selected values
            valid = True
            for prev in current_b:
                if gcd(val, prev) > 1:
                    valid = False
                    break

            if valid:
                used = used | {val}
                current_b.append(val)
                backtrack(idx + 1, current_b, current_cost + abs(a[idx] - val), used)
                current_b.pop()
                used = used - {val}

    backtrack(0, [], 0, set())

    if best_solution is not None:
        return ' '.join(map(str, best_solution))
    else:
        return ' '.join(map(str, a))

