import sys
from functools import lru_cache

def solution(input_str):
    n, k = map(int, input_str.strip().split())

    def complement(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    @lru_cache(maxsize=None)
    def count_representatives(prefix):
        remaining = n - len(prefix)
        if remaining < 0:
            return 0

        if remaining == 0:
            s = prefix

            # Skip all-0 and all-1 strings
            if s == '0' * n or s == '1' * n:
                return 0

            # Check if s is lexicographically minimum in its equivalence class
            s_rev = s[::-1]
            s_comp = complement(s)
            s_comp_rev = s_comp[::-1]

            for other in [s_rev, s_comp, s_comp_rev]:
                if other < s:
                    return 0

            return 1

        # Memoized count
        return count_representatives(prefix + '0') + count_representatives(prefix + '1')

    # Build the k-th representative
    def build_representative(current_prefix):
        # If complete
        if len(current_prefix) == n:
            return current_prefix

        # Try '0' branch
        if current_prefix == '':
            k0 = count_representatives('0')
        else:
            k0 = count_representatives(current_prefix + '0')

        if k <= k0:
            return build_representative(current_prefix + '0')
        else:
            k -= k0
            return build_representative(current_prefix + '1')

    # If k exceeds possible representatives
    total = count_representatives('')
    if k > total:
        return "-1\n"

    result = build_representative('')
    return result + '\n'


